const LABS: LabData[] = [
  {"chapter":"fs-ch01","subject":"fullstack","title":"Web 工作原理：HTTP 与浏览器-服务器交互","fingerprint":"74b0963c2a","scenario":{"work":{"tag":"工作现场","head":"URL 的解剖：协议、主机、端口、路径、查询与片段","body":"用 GET 触发副作用"},"exam":{"tag":"考场视角","head":"HTTP 方法的安全性与幂等性","body":"fs-ch01 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"100KB 响应不压缩，带宽打满","brief":"一个列表接口返回 100KB 的 JSON，线上 1000 QPS。明文发出去就是 97MB/s 的出带宽，单机千兆网卡直接打满、P99 抖动。把响应体大小、QPS 和是否压缩拖一拖，看 gzip 把带宽压到什么程度。","params":[{"key":"payloadKB","label":"单响应体大小","min":80,"max":512,"step":10,"value":100},{"key":"qps","label":"请求速率","min":500,"max":5000,"step":50,"value":1000},{"key":"gzip","label":"是否压缩","min":0,"max":1,"step":1,"value":0,"labels":["明文发送（无 Content-Encoding）","gzip 压缩后"]}],"metrics":[{"key":"ratio","label":"压缩比","expr":"if(gzip == 1, 0.15, 1)","unit":"×","fmt":"fix2"},{"key":"rawMB","label":"每秒原始带宽","expr":"payloadKB * qps / 1024","unit":"MB/s","fmt":"int"},{"key":"perReqMB","label":"单响应实际传输","expr":"payloadKB * ratio / 1024","unit":"MB","fmt":"fix2"},{"key":"outMB","label":"每秒实际带宽","expr":"rawMB * ratio","unit":"MB/s","fmt":"int"}],"checks":[{"expr":"payloadKB >= 80","label":"响应体就是 100KB 上下（列表/详情页的真实体量）"},{"expr":"qps >= 500","label":"至少 500 QPS（线上接口的常态）"},{"expr":"outMB <= 30","label":"实际带宽 ≤30MB/s（千兆网卡要留余量）"},{"expr":"perReqMB <= 0.05","label":"单响应 ≤50KB（与大小无关的单位量判据）"}],"insight":"HTTP 的 `Content-Encoding: gzip`（或 br/zstd）是性价比最高的优化之一：JSON/HTML 这类文本压缩比常常 5~8×，上面的 100KB 响应 gzip 后约 15KB。97MB/s 的明文带宽降到 14MB/s，单机直接多出 6 倍余量。注意三件事：① **反向代理（Nginx）统一开启**最省心，应用层不必每个接口自己压；② **已经压缩过的内容别再压**（图片、视频 gzip 反而变大），按 Content-Type 白名单；③ 压缩有 CPU 成本，极高 QPS 下可以 `gzip_static` 预压缩或交给 CDN 边缘做。"},{"kind":"match","pairs":[{"id":1,"left":"用 GET 触发副作用","right":"写操作一律用 POST/PUT/PATCH/DELETE"},{"id":2,"left":"把错误塞进 200 OK","right":"状态码表达协议级结果，错误详情放响应体"},{"id":3,"left":"302 后被浏览器把 POST 变 GET","right":"POST 成功后返回 303（POST-Redirect-GET 模式）让客户端用 GET 取结果页"},{"id":4,"left":"静态资源不用指纹文件名 + 长强缓存","right":"内容哈希进文件名（app.3f2a1b.js）+ max-age=1y, immutable，更新时文件名变化即天然失效"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"关于 HTTP 方法的**安全性（safe）**与**幂等性（idempotent）**，下列说法正确的是？","title":"HTTP 方法的安全性与幂等性","options":[{"key":"A","text":"GET 是安全的且幂等的，因此网络超时可以放心重试"},{"key":"B","text":"POST 是幂等的，重复提交不会产生副作用"},{"key":"C","text":"PUT 是安全的，因为它只修改资源不创建资源"},{"key":"D","text":"DELETE 不安全但也不幂等，重试会报错"}],"correct":["A"],"explain":"GET 安全（不改服务端状态）且幂等（执行多次效果相同），因此可被预取、缓存，网络层也可自动重试。 B 错：POST 既不安全也不幂等，重复提交会重复创建，必须靠幂等键去重。 C 错：PUT 不安全（会改变状态），但幂等（同一份内容重复 PUT 结果相同）。 D 错：DELETE 不安全，但幂等——删同一个资源，删一次和删多次的最终状态相同。"},{"id":"q1","stem":"某站把 `/old` 临时迁移到 `/new`（几周后会迁回），但有工程师写成了 `301`。另一个接口在 POST 成功后返回 `302` 跳到结果页，导致部分客户端把 POST 变成了 GET。下列判断**正确**的是？","title":"301 / 302 / 307 的差别","options":[{"key":"A","text":"写成 301 没问题，301 和 302 只差一个数字"},{"key":"B","text":"临时迁移应使用 302 或 307；301 会被浏览器长期缓存，难以回滚"},{"key":"C","text":"302 保证方法不变，问题出在客户端实现有 bug"},{"key":"D","text":"POST 后应返回 301 以形成 POST-Redirect-GET 模式"}],"correct":["B"],"explain":"A 错、B 对：301 是永久重定向，浏览器/CDN 会长期缓存，临时迁移用 301 一旦要迁回极难生效。 C 错：302 在历史实现中允许把 POST 改写为 GET，这不是客户端 bug 而是规范遗留；要保证方法不变必须用 307/308。 D 错：POST-Redirect-GET 模式应返回 303 See Other（明确要求用 GET 取新地址），不是 301。"},{"id":"q2","stem":"服务端在一个含用户隐私数据的接口上写了 `Cache-Control: no-cache`，认为这样就「不会缓存、数据不会泄露」。这个判断的问题是？","title":"no-cache 与 no-store 的区别","options":[{"key":"A","text":"没问题，no-cache 就是完全不缓存"},{"key":"B","text":"no-cache 表示「可缓存但每次必须校验」，仍可能被存下来；禁止存储应用 no-store"},{"key":"C","text":"no-cache 等价于 max-age=0，两者完全一致，写法没错"},{"key":"D","text":"隐私数据只需把 max-age 设为 0 即可"}],"correct":["B"],"explain":"A 错、B 对：no-cache 的语义是「可以缓存，但每次使用前必须向服务端校验」，副本仍会被写入缓存；真正「任何情况下都不存储」是 no-store。 C 错：no-cache 与 max-age=0 语义相近但不等价（前者更强制、不依赖启发式新鲜度）。 D 错：隐私数据不仅要禁存储，还应配合 private（避免共享缓存/代理缓存造成越权），更稳妥的是 no-store。"}]},{"kind":"fill","lang":"js","file":"05-http-in-practice.md","code":"// 服务端：给出可缓存的响应，带 ETag；客户端带 If-None-Match，命中就回 304\nconst crypto = require('node:crypto');\n\nconst PAYLOAD = JSON.stringify({ items: [{ id: 'cpp-ch01-01', title: '指针与数组' }] });\nconst etag = '\"' + crypto.createHash('sha1').update(PAYLOAD).digest('hex').slice(0, 8) + '\"';\n\nfunction handle(req, res) {\n  if (req.‹1›['if-none-match'] === etag) {\n    res.writeHead(304, { ETag: etag });\n    return res.end();               // 304 无响应体，省带宽\n  }\n  res.writeHead(200, {\n    'Content-Type': 'application/json; charset=utf-8',\n    'Cache-Control': 'private, max-age=60',\n    ETag: etag,\n  });\n  res.end(PAYLOAD);\n}\n\nmodule.exports = { handle, etag };","marker":"‹%n›","blanks":[{"id":"b1","answer":"headers","line":8}],"distractors":["name","data"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch02","subject":"fullstack","title":"前端基础：HTML 语义化与 CSS 盒模型/布局","fingerprint":"7b017e928f","scenario":{"work":{"tag":"工作现场","head":"语义化页面骨架：header/nav/main/article/aside/foo…","body":"盒模型尺寸算错（content-box 陷阱）"},"exam":{"tag":"考场视角","head":"CSS 中 box-sizing 的默认值是什么？","body":"fs-ch02 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"循环里读写交替，强制同步重排","brief":"要批量更新 1000 个节点的样式并读取它们的位置。如果循环里「写一行样式、读一次 offsetHeight」交替，浏览器每次读都会强制先做一遍布局（reflow），1000 个节点就是 1000 次重排。把节点数和处理模式拖一拖，看卡顿是怎么来的。","params":[{"key":"nodes","label":"节点数","min":100,"max":5000,"step":100,"value":1000},{"key":"pattern","label":"读写模式","min":0,"max":1,"step":1,"value":0,"labels":["循环里读写交替（每次读 offsetHeight 都强制重排）","先批量读、再批量写（只 1 次重排）"]}],"metrics":[{"key":"reflows","label":"重排次数","expr":"if(pattern == 0, nodes, 1)","unit":"次","fmt":"int"},{"key":"costMs","label":"布局耗时","expr":"reflows * 2","unit":"ms","fmt":"int"}],"checks":[{"expr":"nodes >= 500","label":"至少 500 个节点（列表 / 表格的真实规模）"},{"expr":"reflows <= 5","label":"重排 ≤5 次（读写分离的硬判据）"},{"expr":"costMs <= 50","label":"布局耗时 ≤50ms（16ms 一帧，50ms 已掉 3 帧但可接受）"}],"insight":"浏览器的渲染是「JS 执行 → 样式计算 → 布局 → 绘制 → 合成」的流水线，**读几何属性（offsetHeight / offsetTop / getBoundingClientRect / 某些 getComputedStyle）会强制浏览器先 flush 掉之前积攒的写、立即跑一遍布局**——这就是 layout thrashing。循环里「写→读→写→读」等于每轮都重排一次。三条解法：① **读写分离**：先把所有要读的值一次性读出来，再统一写；② **用 DocumentFragment / 脱离文档的节点**做批量改动，只触发一次回流；③ **fast path**：改 class 而不是逐条改 style，交给 CSS 引擎批量处理。现代框架（React/Vue）的虚拟 DOM diff 也是在 commit 阶段统一写，本质就是避免读写交替。"},{"kind":"sequence","heading":"二、实现机制（按线程与阶段拆解）","steps":["解析（Parse）","样式计算（Style / Recalc）","布局（Layout / Reflow）","绘制（Paint）","合成（Composite）"],"file":"03-rendering-pipeline.md"},{"kind":"match","pairs":[{"id":1,"left":"盒模型尺寸算错（content-box 陷阱）","right":"全局 * { box-sizing: border-box; }，让 width 即总宽。"},{"id":2,"left":"用一堆 <div> 拼结构忽略语义","right":"用 header/nav/main/article/section/aside/footer 等地标标签。"},{"id":3,"left":"外边距塌陷（margin collapse）","right":"用 padding/border/overflow:hidden/display:flow-root 阻断（计算见 ex11）。"},{"id":4,"left":"浮动导致父容器高度塌陷","right":"父容器建立 BFC：display:flow-root 或 overflow:hidden（注意裁切副作用）。"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"选择 `box-sizing` 的初始值（未显式设置时）。","title":"CSS 中 box-sizing 的默认值是什么？","options":[{"key":"A","text":"border-box"},{"key":"B","text":"content-box"},{"key":"C","text":"padding-box"},{"key":"D","text":"margin-box"}],"correct":["B"],"explain":"CSS 规范中 box-sizing 初始值为 content-box：width/height 仅含内容区，padding 与 border 额外撑大元素。"},{"id":"q1","stem":"多选思路（本题单选最干净的触发方式）：哪个声明**专门**用于建立 BFC 且无裁切/定位副作用？","title":"以下哪些做法会触发 BFC（块级格式化上下文）？","options":[{"key":"A","text":"display: flow-root"},{"key":"B","text":"color: red"},{"key":"C","text":"font-size: 16px"},{"key":"D","text":"text-align: center"}],"correct":["A"],"explain":"display:flow-root 是语义上最纯粹的 BFC 触发方式，不会导致 overflow:hidden 的裁切或 absolute 的脱离文档流等副作用。"}]},{"kind":"fill","lang":"js","file":"03-rendering-pipeline.md","code":"// 错误：循环里交替读 offsetHeight（强制 reflow）与写 width → 每轮都重排\nfor (const el of boxes) {\n  const h = el.offsetHeight;   // 读：强制同步布局\n  el.style.width = h + 10 + 'px'; // 写：下一轮读前又 reflow\n}\n// 修复：先批量读，再批量写\nconst hs = boxes.map(el => el.offsetHeight);\nboxes.‹1›((el, i) => { el.style.width = hs[i] + 10 + 'px'; });","marker":"‹%n›","blanks":[{"id":"b1","answer":"forEach","line":8}],"distractors":["require","headers"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch03","subject":"fullstack","title":"JavaScript 核心：类型、原型链、DOM 与事件、异步(Promise/async)","fingerprint":"a4b48fdab1","scenario":{"work":{"tag":"工作现场","head":"typeof 对 7 种原始类型与对象/函数的结果","body":"typeof null === 'object'"},"exam":{"tag":"考场视角","head":"typeof 对 null 的结果是什么？","body":"fs-ch03 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"100ms 轮询，空转请求","brief":"前端想实时看订单状态，用 setInterval 每 100ms 打一次接口问「变了吗」。绝大多数请求答案都是「没变」，等于每秒 10 次空转请求打到后端。把轮询间隔和是否用推送拖一拖，看空转量。","params":[{"key":"pollMs","label":"轮询间隔","min":100,"max":5000,"step":100,"value":100},{"key":"usePush","label":"数据获取方式","min":0,"max":1,"step":1,"value":0,"labels":["客户端定时轮询","服务端事件推送（SSE / WebSocket）"]}],"metrics":[{"key":"pollsPerSec","label":"每秒请求数","expr":"if(usePush == 1, 0, 1000 / pollMs)","unit":"次/s","fmt":"int"},{"key":"wastedPerMin","label":"每分钟空转请求","expr":"pollsPerSec * 60","unit":"次","fmt":"int"}],"checks":[{"expr":"pollMs <= 1000","label":"轮询间隔不会太长（默认 100ms 很频繁）"},{"expr":"pollsPerSec <= 0.2","label":"每秒请求 ≤0.2（推送后归零的硬判据）"},{"expr":"wastedPerMin <= 12","label":"每分钟空转 ≤12 次"}],"insight":"轮询（polling）是最容易写的实时方案，但代价是**「询问」和「变化」解耦后的空转**：间隔短了空转多、间隔长了延迟高，永远在两难之间。三种更优的替代：① **长轮询（long-polling）**：请求挂起直到有变化才返回，把空转合并掉；② **SSE（Server-Sent Events）**：服务端单向推送，一条长连接复用；③ **WebSocket**：双向全双工，适合聊天 / 协同编辑。取舍点：读多写少、延迟敏感 → SSE；需要客户端主动发 → WebSocket；纯粹为了「知道变了」却用高频轮询，是典型的资源浪费。"},{"kind":"match","pairs":[{"id":1,"left":"typeof null === 'object'","right":"判对象用 x !== null && typeof x === 'object' && !Array.isArray(x)。"},{"id":2,"left":"用 == 做宽松比较引发隐式转换","right":"默认用 ===，需要容错用 Object.is 或 ??/?.。"},{"id":3,"left":"把 NaN 当普通值比较","right":"用 Number.isNaN(x)（不会把非数字误判成 NaN）。"},{"id":4,"left":"var 循环闭包打印「最后一项」","right":"用 let（每块新绑定）或在循环内 bind(i)。"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"在 JavaScript 中，`typeof null` 的返回值是什么？","title":"typeof 对 null 的结果是什么？","options":[{"key":"A","text":"null"},{"key":"B","text":"object"},{"key":"C","text":"undefined"},{"key":"D","text":"number"}],"correct":["B"],"explain":"typeof null 返回 'object' 是历史包袱（初版 32 位 tag 中 null 的低位标识与对象相同），因此不能用于区分 null 与对象。"},{"id":"q1","stem":"只凭隐式转换规则判断，下列哪个表达式求值为 true？","title":"下面哪条比较结果为 true？","options":[{"key":"A","text":"1 === '1'"},{"key":"B","text":"null == undefined"},{"key":"C","text":"NaN === NaN"},{"key":"D","text":"[] === false"}],"correct":["B"],"explain":"null == undefined 为 true 是规范特例；其余：A 严格相等类型不同为 false；C NaN 不等于自身；D 不同类型无转换直接 false。"},{"id":"q4","stem":"`const obj = { name: 'o', fn() { const g = () => this.name; return g(); } }; obj.fn()` 的返回值是？","title":"箭头函数里的 this 来自哪里？","options":[{"key":"A","text":"undefined（箭头没有 this）"},{"key":"B","text":"String 'o'（捕获了 fn 的 this 即 obj）"},{"key":"C","text":"全局对象的 name"},{"key":"D","text":"运行时报错"}],"correct":["B"],"explain":"箭头函数没有自己的 this，取定义时外层词法作用域（fn 调用时的 this=obj）的 this，因此返回 'o'。"}]},{"kind":"fill","lang":"js","file":"01-types-coercion.md","code":"const samples = [\n  ['number', 1],\n  ['string', 'a'],\n  ['boolean', true],\n  ['null', null],\n  ['undefined', undefined],\n  ['symbol', Symbol('s')],\n  ['bigint', 10n],\n  ['object', {}],\n  ['array', []],\n  ['function', function(){}],\n];\nfor (const [name, v] of samples) {\n  ‹1›.log(name, '=>', typeof v);\n}","marker":"‹%n›","blanks":[{"id":"b1","answer":"console","line":14}],"distractors":["data","json"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch04","subject":"fullstack","title":"Node.js 与后端 API","fingerprint":"fe87cde25b","scenario":{"work":{"tag":"工作现场","head":"事件循环阶段顺序：sync → nextTick → microtask → se…","body":"在顶层脚本里认为 setTimeout(0) 一定先于 setImmediate"},"exam":{"tag":"考场视角","head":"Node.js 最适合哪类场景？","body":"fs-ch04 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"Node 一次性 readFile 大文件","brief":"要处理一个 500MB 的导出文件。fs.readFile 会把它整个读进内存再回调，内存峰值就是 500MB——容器内存限制 256MB 时直接 OOM 被 kill。换成流分块读，峰值只有 64KB。把文件大小和读取方式拖一拖，看内存峰值。","params":[{"key":"fileMB","label":"文件大小","min":100,"max":2000,"step":50,"value":500},{"key":"streaming","label":"读取方式","min":0,"max":1,"step":1,"value":0,"labels":["fs.readFile 一次性读进内存","fs.createReadStream 分块（64KB）"]}],"metrics":[{"key":"peakMB","label":"内存峰值","expr":"if(streaming == 1, 64, fileMB)","unit":"MB","fmt":"int"},{"key":"chunks","label":"数据块数","expr":"if(streaming == 1, fileMB * 1024 / 64, 1)","unit":"块","fmt":"int"}],"checks":[{"expr":"fileMB >= 200","label":"至少 200MB（日志 / 导出文件的真实体量）"},{"expr":"peakMB <= 128","label":"内存峰值 ≤128MB（容器常见限制）"}],"insight":"Node 是单进程，**一次性把大文件读进内存既撑爆 V8 堆又加长 GC 停顿**。Stream 的核心价值是**边读边处理 + 背压**：下游消费慢时，上游自动暂停推数据，内存峰值恒定在「一个 chunk」大小（默认 64KB）。两个要点：① 用 `stream.pipe(dest)` 或 `for await (const chunk of readable)` 而不是 readFile；② 网络 / 磁盘 / 压缩（zlib）之间用 pipe 串联，Node 会自动在两端速率不匹配时做背压，不会堆积。需要随机访问大文件时再考虑 mmap（Node 用 `fs.open` + `read` 按 offset 读）。"},{"kind":"match","pairs":[{"id":1,"left":"在顶层脚本里认为 setTimeout(0) 一定先于 setImmediate","right":"需要「下一轮 check 阶段立即执行」用 setImmediate；只在 I/O 回调内顺序才稳定为 setImmediate 先。"},{"id":2,"left":"process.nextTick 里无限递归导致微任务饥饿","right":"让出事件循环改用 setImmediate，避免无限递归推入 nextTick。"},{"id":3,"left":"用 fs.readFileSync 等同步 API 阻塞主线程","right":"用异步 API，或把重 I/O 放 worker_threads / 改用流分块读取。"},{"id":4,"left":"HTTP 响应忘了 res.end()","right":"任何分支都必须 res.end()（或 write 后 end），错误分支也要 end。"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"基于 Node 的单线程事件循环模型，下列哪一项是它的典型优势场景？","title":"Node.js 最适合哪类场景？","options":[{"key":"A","text":"CPU 密集型科学计算"},{"key":"B","text":"高并发 I/O 密集型网络服务"},{"key":"C","text":"海量内存图计算"},{"key":"D","text":"GPU 模型训练"}],"correct":["B"],"explain":"Node 单线程事件循环擅长非阻塞 I/O，适合高并发网络服务；CPU 密集任务会饿死事件循环，应放 worker_threads。"},{"id":"q1","stem":"下列关于 Node 模块系统的说法，哪一项正确？","title":"关于 CommonJS 与 ESM，正确的是？","options":[{"key":"A","text":"require 是异步加载"},{"key":"B","text":"ESM 的 import 是静态可分析的、支持 tree-shaking"},{"key":"C","text":"module.exports 与 exports 是两个互相独立的对象"},{"key":"D","text":"CommonJS 循环依赖下永远拿到完整 exports"}],"correct":["B"],"explain":"ESM 的 import/export 在编译期可静态分析，支持 tree-shaking；require 同步；exports 是 module.exports 的别名；CJS 循环依赖可能拿到半截（undefined）exports。"},{"id":"q7","stem":"对于 `const buf = Buffer.from('你好', 'utf8'); buf.subarray(1).toString('utf8')`，结果特征是？","title":"Buffer 按字节切片会怎样？","options":[{"key":"A","text":"正常得到「好」，无影响"},{"key":"B","text":"在码点中间切断，产生替换符（U+FFFD）乱码"},{"key":"C","text":"抛出 RangeError"},{"key":"D","text":"返回空字符串"}],"correct":["B"],"explain":"UTF-8 变长编码，subarray(1) 从字节 1 切断「你」（3 字节）得到非法序列，解码替换为 U+FFFD；应按字符（string.slice）或 StringDecoder 处理。"}]},{"kind":"fill","lang":"js","file":"02-http-server-middleware.md","code":"function compose(middlewares) {\n  return function (ctx) {\n    let last = -1;                       // 防止同一个中间件里 next() 被调两次\n    function dispatch(i) {\n      if (i <= last) return Promise.reject(new Error(\"next() ‹1› multiple times\"));\n      last = i;\n      const fn = middlewares[i];\n      if (!fn) return Promise.resolve();\n      try {\n        return Promise.resolve(fn(ctx, () => dispatch(i + 1)));\n      } catch (err) {\n        return Promise.reject(err);\n      }\n    }\n    return dispatch(0);\n  };\n}\n\nconst mw = [\n  async (ctx, next) => { ctx.log.push(\"A-in\");  await next(); ctx.log.push(\"A-out\"); },\n  async (ctx, next) => { ctx.log.push(\"B-in\");  await next(); ctx.log.push(\"B-out\"); },\n];\n\nconst ctx = { log: [] };\ncompose(mw)(ctx).then(() => ‹2›.log(ctx.log));\n// [ 'A-in', 'B-in', 'B-out', 'A-out' ]","marker":"‹%n›","blanks":[{"id":"b1","answer":"called","line":5},{"id":"b2","answer":"console","line":25}],"distractors":["headers","stringify"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch05","subject":"fullstack","title":"数据库与 REST API 设计","fingerprint":"5dfa29d989","scenario":{"work":{"tag":"工作现场","head":"RESTful 资源命名、HTTP 方法语义（安全/幂等）与状态码映射表（纯函数，…","body":"用 offset 深分页，还在并发写入下翻页"},"exam":{"tag":"考场视角","head":"什么场景更适合选文档型（MongoDB）","body":"fs-ch05 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"深度分页 OFFSET 深翻页","brief":"一个千万行的订单表，前端「下一页」翻到第 1000 页。LIMIT 10 OFFSET 100000 看起来只取 10 行，但数据库得先扫出前 100000 行再丢弃，越翻越慢。把总行数、页码和分页方式拖一拖，看扫描行数。","params":[{"key":"totalRows","label":"表总行数","min":100000,"max":10000000,"step":500000,"value":5000000},{"key":"page","label":"翻到第几页","min":1,"max":1000,"step":20,"value":1000},{"key":"perPage","label":"每页条数","min":10,"max":100,"step":10,"value":10},{"key":"cursor","label":"分页方式","min":0,"max":1,"step":1,"value":0,"labels":["OFFSET 深翻页","游标分页（WHERE id > lastId）"]}],"metrics":[{"key":"offset","label":"OFFSET 值","expr":"page * perPage","unit":"行","fmt":"int"},{"key":"scanned","label":"本次扫描行数","expr":"if(cursor == 1, perPage, offset + perPage)","unit":"行","fmt":"int"},{"key":"scanMB","label":"本次扫描数据量","expr":"scanned * 200 / 1048576","unit":"MB","fmt":"fix2"}],"checks":[{"expr":"totalRows >= 1000000","label":"至少千万级大表（深翻页才会痛）"},{"expr":"page >= 100","label":"确实翻到了很深的页"},{"expr":"scanned <= 100","label":"本次扫描 ≤100 行（游标分页的硬判据）"},{"expr":"scanMB <= 0.05","label":"扫描数据 ≤50KB（与页码无关的单位量）"}],"insight":"`OFFSET` 是「跳过前 N 行」，数据库**没有捷径**，必须真的先把前 N 行从存储读出来（即使丢弃）。翻到第 1000 页就是扫 10000 行，深翻页随着页码线性变慢，还会因 MVCC 反复读旧版本。游标分页（keyset pagination）用索引列做范围：`WHERE id > :lastId ORDER BY id LIMIT 10`，无论翻多深都只扫一页，**前提是排序列有索引且稳定**（所以别用 `ORDER BY rand()`）。限制：游标分页不支持「跳到第 N 页」的随机跳转，UI 上用「无限滚动 / 上一页下一页」替代页码输入即可。"},{"kind":"match","pairs":[{"id":1,"left":"用 offset 深分页，还在并发写入下翻页","right":"翻页用游标（keyset）：WHERE (sort_key, id) < (cursor_key, cursor_id)，且游标必须包含完整排序键（含唯一键）。"},{"id":2,"left":"复合索引列序按「选择性高到低」排","right":"按最左前缀的实际查询组合排：等值条件列在前、范围条件列在后；ex09 的 (tenant_id, kind) 同时支持 tenant_id=? AND kind=? 与 tenant_id=? AND kind>?。"},{"id":3,"left":"以为「建了索引就一定走索引」","right":"以计划串为唯一判据：出现 SEARCH ... USING INDEX 才是走了索引，SCAN 就是没走；建索引后必须复查计划。"},{"id":4,"left":"以为「只查主键就一定覆盖」或「有索引就一定覆盖」","right":"覆盖的判定是「查询涉及的所有列 ⊆ 索引列 ∪ 主键」，多一个非索引列就需要回表。"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"fs-ch05-ex01","stem":"按「一次业务操作能否落在同一个聚合根内」这一判据，下列哪种场景最适合选文档型数据库？","title":"什么场景更适合选文档型（MongoDB）","options":[{"key":"A","text":"需要跨多张表保证「扣库存 + 建订单」的原子性"},{"key":"B","text":"读多写少、需要对多表做任意 JOIN 与聚合报表"},{"key":"C","text":"一次读取就把一个聚合根（含嵌套子结构）整体取回，且几乎不跨聚合 JOIN"},{"key":"D","text":"需要严格的外键约束防止脏数据"}],"correct":["C"],"explain":"文档型把聚合边界编码进物理布局，整存整取极快。A 需要跨文档事务（关系型更省心）、B 与 D 都需要关系型的 JOIN 与约束能力。选型判据是「聚合边界是否与写入边界重合」，不是性能数字。"},{"id":"fs-ch05-ex02","stem":"表 events 上有复合索引 idx_tenant_kind(tenant_id, kind)。查询需要返回列 tenant_id、kind 以外的 payload 列时，下列哪条 WHERE 无法利用该索引的最左前缀定位行？","title":"复合索引 (tenant_id, kind) 上哪条查询无法用索引定位","options":[{"key":"A","text":"WHERE tenant_id = ?"},{"key":"B","text":"WHERE tenant_id = ? AND kind = ?"},{"key":"C","text":"WHERE tenant_id = ? AND kind > ?"},{"key":"D","text":"WHERE kind = ?"}],"correct":["D"],"explain":"索引只在 (tenant_id, kind) 这个列序上有序，(kind) 单独不是任何前缀，无法定位起点。本章 ex09 实跑显示该查询的计划退化为 SCAN events（uses_index=False）。"},{"id":"fs-ch05-ex07","stem":"关于 RFC 9457（Problem Details for HTTP APIs），下列说法哪一项正确？","title":"Problem Details 的成员与媒体类型","options":[{"key":"A","text":"媒体类型是 application/json，错误体与成功资源共用同一结构"},{"key":"B","text":"核心成员为 type / title / status / detail / instance，允许添加不与核心成员冲突的扩展成员"},{"key":"C","text":"type 必须是绝对 URL，不允许使用 about:blank 作为缺省值"},{"key":"D","text":"字段级校验错误必须直接平铺在顶层，不能用扩展成员承载"}],"correct":["B"],"explain":"RFC 9457 的媒体类型是 application/problem+json，五个核心成员为 type/title/status/detail/instance；type 缺省为 about:blank，且允许相对 URI 引用；扩展成员（如 errors 数组、retryAfterSec）可自由添加但不得与核心成员冲突。本章 ex06 实跑验证了这一点。"}]}]},
  {"chapter":"fs-ch06","subject":"fullstack","title":"用户认证 / JWT / 鉴权","fingerprint":"4657f646a2","scenario":{"work":{"tag":"工作现场","head":"JWT 三段结构与 base64url 编解码（Node 内置 Buffer）","body":"把「认证」和「鉴权」混为一谈，失败码一律 401"},"exam":{"tag":"考场视角","head":"401 与 403 的语义边界","body":"fs-ch06 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"密码存储：明文 vs bcrypt","brief":"用户密码只有 8 位（大小写+数字）。如果数据库明文存、或只存一个 MD5，泄露后被 GPU 每秒枚举十亿次，几秒就全破。换成 bcrypt（故意慢哈希）后，同样一个密码要算几百年。把存储方案和密码长度拖一拖，看破解时间。","params":[{"key":"scheme","label":"存储方案","min":0,"max":3,"step":1,"value":0,"labels":["明文","快哈希（MD5 / SHA-1）","加盐快哈希","bcrypt 慢哈希"]},{"key":"pwdLen","label":"密码长度","min":6,"max":16,"step":1,"value":8}],"metrics":[{"key":"guessesPerSec","label":"每秒可试密码数","expr":"if(scheme == 0, 1000000000000, if(scheme == 1, 1000000000, if(scheme == 2, 1000000000, 10)))","unit":"次/s","fmt":"int"},{"key":"keyspace","label":"密码空间","expr":"pow(62, pwdLen)","unit":"种","fmt":"int"},{"key":"crackSec","label":"破解耗时（平均）","expr":"keyspace / guessesPerSec / 2","unit":"秒","fmt":"int"},{"key":"crackYears","label":"破解耗时（年）","expr":"crackSec / 31536000","unit":"年","fmt":"int"}],"checks":[{"expr":"pwdLen <= 10","label":"用户就是弱密码（≤10 位才是真实风险）"},{"expr":"crackYears >= 1000","label":"破解 ≥1000 年（bcrypt 的硬判据）"}],"insight":"密码存储的第一原则：**永远别存明文，也别用快哈希（MD5/SHA-1/SHA-256）**。 快哈希的设计目标是「快」，正好让攻击者的 GPU 农场每秒枚举几十亿个候选。正确做法是**慢哈希 + 每用户盐**：bcrypt / scrypt / Argon2 故意把单次计算做慢（bcrypt 默认约 100ms/次，且可随硬件升级调 cost），并给每个用户随机盐，让「彩虹表」失效、相同密码也存出不同摘要。现代框架（Django/Spring Security/Passlib）默认就走这套；如果还在手写 `md5(password)`，这是最需要优先修的安全债。"},{"kind":"match","pairs":[{"id":1,"left":"把「认证」和「鉴权」混为一谈，失败码一律 401","right":"按 ex11 的链式职责分流：no_token/bad_scheme → 401，valid_but_no_perm → 403，valid_with_perm → 200；前端据此分别「跳登录」与「提示无权限」。"},{"id":2,"left":"只做接口级鉴权，不做资源级校验（水平越权 / IDOR / BOLA）","right":"在授权中间件之后再加资源级校验：比对 resource.ownerId === actor.id；ex12 中 editor_delete_others=false…"},{"id":3,"left":"JWT 校验只验签名，不验 exp/nbf/aud/iss","right":"上全清单：段数、alg 白名单、常量时间验签、exp、nbf、aud、iss。ex06 实跑：expired、nbf_future、aud_wrong、iss_wrong、missing_exp 全部被拒。"},{"id":4,"left":"让 token 头里的 alg 决定验签算法（或接受 alg: none）","right":"alg 由服务端写死/白名单；ex05 中朴素实现 alg_none_naive_accepts=true 被打穿，安全实现 alg_none_secure=alg-pinned-reject。"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"fs-ch06-ex01","stem":"一个已登录用户（token 合法）请求 `DELETE /articles/42`，但缺少 `article:delete` 权限。服务端应返回哪个状态码，为什么？","title":"401 与 403 的语义边界","options":[{"key":"A","text":"401，因为用户无权执行该操作"},{"key":"B","text":"403，因为凭证有效但授权不足"},{"key":"C","text":"400，因为请求非法"},{"key":"D","text":"500，因为服务端无法处理"}],"correct":["B"],"explain":"401 Unauthorized 的真实含义是「未认证」（缺或坏的凭证，须带 WWW-Authenticate）；403 Forbidden 才是「已认证但无权」。本例凭证合法、仅权限不足，故为 403。本章 ex11 实跑 valid_but_no_perm status=403。"},{"id":"fs-ch06-ex02","stem":"关于 Session + Cookie 与 JWT 的对比，下列说法正确的是：","title":"Session 与 JWT 在「主动失效 / 水平扩展」上的取舍","options":[{"key":"A","text":"JWT 天然支持服务端即时撤销，Session 不行"},{"key":"B","text":"Session 可即时撤销但需共享会话存储，JWT 无需共享状态但无法主动失效"},{"key":"C","text":"两者都把状态存在客户端，因此都能水平扩展"},{"key":"D","text":"JWT 的内容是加密的，所以可以安全地存放敏感信息"}],"correct":["B"],"explain":"Session 状态在服务端，撤销即时，但多实例要共享存储（Redis）或粘性会话；JWT 状态在客户端（自包含），验签即可横向扩展，但签发后到 exp 之前无法主动失效（缓解见 concept/03）。C 错在 Session 状态不在客户端；D 错在 JWT 只是 base64url 编码，不是加密。"}]},{"kind":"fill","lang":"js","file":"05-jwt-in-practice.md","code":"// 令牌版本号：用户改密码/封禁时 +1，旧令牌全部作废（不用逐条存黑名单）\nasync function issueTokens(user, store) {\n  const tokenVersion = await store.getTokenVersion(user.id);\n  const access = sign({ sub: user.id, name: user.nickname, tv: tokenVersion });\n  const refresh = sign({ sub: user.id, kind: 'refresh', tv: tokenVersion }, { expiresIn: '30d' });\n  // 刷新令牌只存哈希，落库/Redis\n  await store.saveRefreshHash(user.id, hash(refresh));\n  return { access, refresh };\n}\n\nasync function authenticate(req, store) {\n  const claims = verify(req.headers.authorization?.replace('Bearer ', '') || req.cookies.access);\n  const user = await store.findById(claims.sub);\n  if (!user || user.‹1›) throw new Error('user invalid');\n  const current = await store.getTokenVersion(user.id);\n  if (current !== claims.tv) throw new Error('‹2› revoked');   // 改密/登出后失效\n  return user;\n}","marker":"‹%n›","blanks":[{"id":"b1","answer":"disabled","line":14},{"id":"b2","answer":"token","line":16}],"distractors":["require","stringify"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch07","subject":"fullstack","title":"全栈项目实战（GitHub 资源驱动）","fingerprint":"130b823af2","scenario":{"work":{"tag":"工作现场","head":"状态容器：reducer 风格 store（dispatch -> 新状态，不可变…","body":"把服务端状态和客户端状态一锅端进全局 store"},"exam":{"tag":"考场视角","head":"下列哪一项属于「服务端状态」而非「客户端状态」","body":"fs-ch07 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"状态放顶层，整树重渲染","brief":"一个 1000 节点的后台页面，把共享状态放在最顶层。任意子组件更新这个状态，整棵组件树都会被标记为需要重新渲染（diff），1000 个节点全量比对。把状态下沉到最小公共祖先、或用 store 的局部订阅后，每次更新只波及 20 个节点。把节点数和状态位置拖一拖，看单次更新参与渲染的节点数。","params":[{"key":"nodes","label":"组件节点数","min":100,"max":5000,"step":100,"value":1000},{"key":"localState","label":"状态位置","min":0,"max":1,"step":1,"value":0,"labels":["状态放顶层（任意子更新触发整树 diff）","状态下沉到最小公共祖先 / store 局部订阅"]}],"metrics":[{"key":"renderNodes","label":"每次更新参与渲染节点","expr":"if(localState == 1, 20, nodes)","unit":"个","fmt":"int"},{"key":"renderMs","label":"单次更新耗时","expr":"renderNodes * 0.05","unit":"ms","fmt":"fix2"}],"checks":[{"expr":"nodes >= 500","label":"至少 500 个节点（真实页面组件树体量）"},{"expr":"renderNodes <= 100","label":"每次更新 ≤100 节点（状态下沉的硬判据）"},{"expr":"renderMs <= 10","label":"单次更新 ≤10ms"}],"insight":"「状态放得越高，重渲染范围越大」是 UI 性能的第一性原理（React/Vue 都适用）。顶层 state 一旦变化，其所有后代默认都会进入 reconcile/diff 队列——即使它们的 props 没变，纯函数 diff 本身也要花时间。三条解法：① **状态下沉**：把 state 移到「真正用到它的最小公共祖先」，父组件不持有它就不会被牵连；② **记忆化**：React.memo / Vue 的静态提升 + v-memo，让 props 未变的子节点跳过 diff；③ **细粒度订阅**：状态库（Redux/Zustand/Pinia）按 selector 订阅，只有用到该字段的组件才更新。经验法则：**状态离使用它的组件越近越好**。"},{"kind":"match","pairs":[{"id":1,"left":"把服务端状态和客户端状态一锅端进全局 store","right":"分两类：服务端状态交给专用数据层（本章 ex04 的 TTL/SWR、ex02 的去重取消、ex09 的分页合并），客户端状态用组件本地 state 或轻量 store（ex01）。"},{"id":2,"left":"以为「状态变了才重渲染」是自动的","right":"未知 action 必须原样返回旧引用：本章 ex01 实跑 unknown_action_keeps_identity=true 且 renders_after_noop_action=3（3 次真实变更对应 3 次…"},{"id":3,"left":"乐观更新只写「成功路径」，不写回滚","right":"乐观更新必须具备三件套：临时 id、失败回滚、并发有序结算。本章 ex03 用正反两组证明：成功 success_count_kept=true（保留且 id 由 tmp-1 变 101）…"},{"id":4,"left":"并发请求同一资源重复发出、且不取消过期请求","right":"in-flight map 去重 + 取消过期请求。ex02 实跑：3 个并发同 key 只发 1 次（sent_while_inflight=1，deduped_flags=false,true,true）…"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"fs-ch07-ex01","stem":"按本章「刷新页面后是否还需要从服务器重新获取」这一判据，下列哪一项最应被建模为服务端状态（交给缓存/数据层）？","title":"下列哪一项属于「服务端状态」而非「客户端状态」","options":[{"key":"A","text":"当前打开的模态框是否可见"},{"key":"B","text":"用户刚在下拉框里选择的筛选条件"},{"key":"C","text":"文章列表（可被其他用户修改、随时可能过期）"},{"key":"D","text":"输入框中尚未提交的草稿文本"}],"correct":["C"],"explain":"服务端状态的特征是「服务端是唯一事实来源、前端只持有可过期的副本」，需要 TTL/失效/去重/重试（本章 ex04/ex02/ex09）。A 弹窗可见性是纯 UI 状态；B 筛选条件与 D 草稿属于客户端状态，本地存活即可，刷新后无需从服务器恢复。"},{"id":"fs-ch07-ex02","stem":"数据驱动视图有四态：loading / success / empty / error。关于 empty 为何要独立成态，下列说法哪一项最准确？","title":"为什么「空结果」必须是独立状态而不是 success 的分支","options":[{"key":"A","text":"empty 与 success 在信息论上等价，只是为了代码好看才拆开"},{"key":"B","text":"empty 对应的用户行为与 success 不同（需引导创建 / 更换筛选条件），合并会丢失这一信息"},{"key":"C","text":"empty 状态一定意味着请求失败，必须显示错误"},{"key":"D","text":"empty 只能在服务端返回 404 时进入"}],"correct":["B"],"explain":"empty 是「请求成功但结果为空」，用户需要的是「创建第一条 / 换个筛选条件 / 换个关键词」等引导，与有数据时的展示行为不同。状态粒度应等于「用户可区分的行为」粒度。本章 ex05 实跑 empty=loading->empty，与 success 是两条不同转移。empty 不是错误（C 错），也不是 404（D 错）。"}]}]},
  {"chapter":"fs-ch08","subject":"fullstack","title":"部署 / CI-CD / Docker","fingerprint":"e192225315","scenario":{"work":{"tag":"工作现场","head":"Dockerfile 静态检查器：指令顺序合理性、fixed tag、多阶段 --…","body":"把 apt-get update 与 apt-get install 拆成两条 RUN"},"exam":{"tag":"考场视角","head":"改一行源码会重建几层：deps-first 与 COPY . . 反模式对照","body":"fs-ch08 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"Docker 单阶段镜像含构建工具","brief":"一个 Java 服务，单阶段 Dockerfile 直接在最终镜像里 `apt install openjdk`，再 COPY 源码编译。最终镜像既含 JDK（~600MB）又含 ubuntu 基础（~70MB），体积 720MB，传输和启动都慢。多阶段只把 jar 拷进 distroless，7MB。把是否含构建工具链和基础镜像拖一拖，看最终体积。","params":[{"key":"buildTool","label":"最终镜像是否含构建工具","min":0,"max":1,"step":1,"value":1,"labels":["最终镜像含构建工具（gcc / JDK / node）","多阶段只 COPY 运行时产物"]},{"key":"baseImg","label":"基础镜像","min":0,"max":2,"step":1,"value":0,"labels":["ubuntu（~70MB）","debian-slim（~30MB）","distroless / alpine（~5MB）"]}],"metrics":[{"key":"baseMB","label":"基础镜像体积","expr":"if(baseImg == 0, 70, if(baseImg == 1, 30, 5))","unit":"MB","fmt":"int"},{"key":"toolchainMB","label":"构建工具链体积","expr":"if(buildTool == 1, 600, 0)","unit":"MB","fmt":"int"},{"key":"depsMB","label":"运行时依赖体积","expr":"if(baseImg == 2, 2, 50)","unit":"MB","fmt":"int"},{"key":"imageMB","label":"最终镜像体积","expr":"baseMB + toolchainMB + depsMB","unit":"MB","fmt":"int"}],"checks":[{"expr":"imageMB <= 100","label":"最终镜像 ≤100MB（单阶段 ubuntu 720MB 会爆）"},{"expr":"toolchainMB == 0","label":"运行时镜像不含构建工具（多阶段的硬判据）"}],"insight":"Docker 镜像分层的妙处不止缓存，**多阶段构建（multi-stage）还能让「构建环境」和「运行环境」彻底分离**：第一阶段用完整的 SDK 镜像编译，第二阶段从一个极小的运行时镜像（distroless / alpine）只 `COPY` 编译产物。收益有三：① 体积从几百 MB 降到几 MB，拉取和冷启动都快；② 攻击面骤减（运行镜像里没有 shell / 包管理器 / 编译器）；③ 构建工具链的 CVE 不会带进生产镜像。另外 `COPY . .` 要写在 `RUN npm install` **之后**、依赖文件单独 COPY 在前，才能命中 layer 缓存——这条和镜像体积同样重要。"},{"kind":"match","pairs":[{"id":1,"left":"把 apt-get update 与 apt-get install 拆成两条 RUN","right":"写在同一 RUN：RUN apt-get update && apt-get install -y --no-install-recommends curl && rm -rf /var/lib/apt/lists/*；"},{"id":2,"left":"基础镜像用 node:latest 或不带 tag","right":"固定到具体版本（node:22.11-bookworm）或直接固定 digest；ex01 对 node:latest 报 base_image_latest:node:latest。"},{"id":3,"left":"先 COPY . . 再 RUN npm ci（依赖安装顺序倒置）","right":"先 COPY package.json package-lock.json ./ → RUN npm ci → 再 COPY . .。"},{"id":4,"left":"不写 .dockerignore","right":"用 .dockerignore 排除（ex04 实测 node_modules/dist/.git/**/*.log/coverage/ 被排除）；注意取反规则 !"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"fs-ch08-ex01","stem":"Dockerfile A 的顺序是 `FROM` → `WORKDIR` → `COPY package.json package-lock.json ./` → `RUN npm ci` → `COPY . .` → `RUN npm run build`（共 6 层）；Dockerfile B 把 `COPY . .` 提前到 `RUN npm ci` 之前（共 5 层）。现在只修改 `src/app.js` 一行并重新构建（不改 `package.json`）。下列说法哪一项与本章实跑结果一致？","title":"改一行源码会重建几层：deps-first 与 COPY . . 反模式对照","options":[{"key":"A","text":"A 重建 2 层且 npm ci 层命中缓存；B 重建 3 层且 npm ci 层被迫重跑"},{"key":"B","text":"A 重建 3 层；B 重建 2 层"},{"key":"C","text":"两者都只重建 1 层（只有 COPY . . 那一层失效）"},{"key":"D","text":"两者都会让全部层重建，因为构建缓存按整份上下文哈希"}],"correct":["A"],"explain":"构建缓存是前缀链：某层失效则其后全部重建，因此「失效点之后的层数」就是重建层数。ex02 实测：A 的 COPY . . 是第 5 层，命中前 4 层、重建 2 层，且 npm_ci_layer_rebuild=False；B 的 COPY . . 是第 3 层，后面还有两条 RUN，命中 2 层、重建 3 层，且 npm_ci_layer_rebuild=True（最贵的依赖安装被反复触发）。缓存键是「父层哈希 + 指令 + 该指令用到的上下文内容」，不是整份上下文的哈希，所以 D 错。"},{"id":"fs-ch08-ex02","stem":"按 12-Factor 的「配置」因子，下列哪种做法属于**违规**（而不是「可接受但可改进」）？","title":"12-Factor 视角下哪种做法违规","options":[{"key":"A","text":"把 LOG_LEVEL 放在外部配置文件 config/default.json，由代码读取"},{"key":"B","text":"把数据库连接串从环境变量 process.env.DATABASE_URL 读取"},{"key":"C","text":"把 STRIPE_SECRET_KEY 直接写在 src/pay.js 源码里"},{"key":"D","text":"把特性开关 FEATURE_NEW_UI 从环境变量读取"}],"correct":["C"],"explain":"12-Factor 的「配置」指会因部署环境而不同的东西，必须与代码分离。环境变量是推荐形态（B、D 合规）；外部配置文件属于「已外置但不如环境变量」（A 记 ok_externalized_but_prefer_env，可接受）；写死在源码里是违规，若该项还是密钥则升级为 critical——因为密钥会随 Git 历史永久存在，且轮换前一直有效。ex11 对 C 这类项输出 VIOLATION_CRITICAL_HARDCODED_SECRET，最终 compliant=5 violations=3 critical=2。"}]}]},
  {"chapter":"fs-ch09","subject":"fullstack","title":"TypeScript：结构化类型、泛型与类型收窄","fingerprint":"8ef3710b71","scenario":{"work":{"tag":"工作现场","head":"结构类型：多一个成员不报错，少一个报错","body":"把 any 当「先跑通再说」"},"exam":{"tag":"考场视角","head":"关于 TypeScript 的结构类型，正确的是","body":"fs-ch09 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"TS 泛型擦除 vs C++ 模板膨胀","brief":"一个泛型容器 `Box<T>` 被 20 种类型实例化。很多人以为「泛型会像 C++ 模板那样每种类型生成一份代码」，其实 TypeScript 的泛型在编译成 JS 后**完全擦除**——`Box<number>` 和 `Box<string>` 是同一份 JS。把类型数量和语言拖一拖，看额外产物体积。","params":[{"key":"types","label":"泛型实例化类型数","min":2,"max":50,"step":1,"value":20},{"key":"lang","label":"语言","min":0,"max":1,"step":1,"value":1,"labels":["TypeScript（泛型擦除）","C++（模板每类型实例化一份）"]}],"metrics":[{"key":"perTypeKB","label":"每类型额外体积","expr":"if(lang == 0, 0, 3)","unit":"KB","fmt":"int"},{"key":"extraKB","label":"额外产物","expr":"types * perTypeKB","unit":"KB","fmt":"int"},{"key":"extraMB","label":"额外产物（MB）","expr":"extraKB / 1024","unit":"MB","fmt":"fix2"}],"checks":[{"expr":"types >= 10","label":"至少被 10 种类型使用（泛型容器的真实处境）"},{"expr":"extraMB == 0","label":"TS 编译后泛型 0 额外体积（擦除的硬判据）"}],"insight":"这是 TS 和 C++ 泛型**最本质的区别**：C++ 模板是图灵完备的「代码生成器」，**每用一种类型就真编译出一份机器码**（所以 `std::vector<int>` 和 `std::vector<double>` 是两份代码，模板元编程能跑会显著增加二进制体积）；而 TypeScript 的类型系统**只在编译期存在**，类型信息（包括泛型参数）在 emit 成 JS 时被整体擦除，运行时只有一份无类型的 JS——所以「泛型会膨胀产物」在 TS 里是**误解**。代价是：TS 无法在运行时做基于类型的分发（需要 `typeof` / `instanceof` / 自定义 type guard 来窄化），也不能像 Java 那样 `T.class`。理解擦除才能正确设计运行时行为。"},{"kind":"match","pairs":[{"id":1,"left":"把 any 当「先跑通再说」","right":"外部入口用 unknown，进门第一步收窄或 schema 校验"},{"id":2,"left":"用 as 代替类型守卫","right":"改成 const user = UserSchema.parse(data)（Zod）"},{"id":3,"left":"以为泛型能约束运行时","right":"要么传入构造函数做 instanceof，要么传入 schema 做运行时校验"},{"id":4,"left":"用 interface 期望拦住多余字段","right":"需要严格排他时用可辨识联合 + never 检查，或在边界处用 schema 的 .strict()"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"选择**正确**的描述。","title":"关于 TypeScript 的结构类型，正确的是","options":[{"key":"A","text":"结构类型要求两个类型声明继承自同一个父类型才能互相赋值"},{"key":"B","text":"结构类型只比较成员形状：多出成员合法，缺少必需成员不合法"},{"key":"C","text":"结构类型在运行时也会检查对象形状，因此能替代数据校验"},{"key":"D","text":"结构类型下 { id: string } 与 { orderId: string } 不能互相赋值"}],"correct":["B"],"explain":"结构类型比形状不比名字：具备所需成员即可赋值，多出的成员不报错、缺少必需成员报错。类型在运行时被擦除，不做任何检查，因此不能替代数据校验。A 描述的是名义类型；D 恰好说反了——同形状不同类型在结构类型下可以互相赋值，这正是需要品牌类型的原因。"},{"id":"q3","stem":"关于 `unknown`，正确的是","title":"unknown 与 any 的差别","options":[{"key":"A","text":"unknown 与 any 完全等价，只是写法不同"},{"key":"B","text":"unknown 能接受任何值，但使用前必须先收窄，否则编译报错"},{"key":"C","text":"unknown 只能用于函数参数，不能用于变量"},{"key":"D","text":"unknown 会在运行时做类型检查，any 不会"}],"correct":["B"],"explain":"unknown 是类型系统的「安全顶」：任何值都能赋给它，但它不能直接参与运算或取属性，必须先收窄（typeof / 守卫 / 断言）。any 则双向通行、跳过所有检查。二者在运行时都不存在，所以 D 错误。C 也错——let x: unknown 完全合法。"}]},{"kind":"fill","lang":"ts","file":"02-narrowing-and-exhaustive.md","code":"function area(shape: Shape): number {\n  switch (shape.‹1›) {\n    case \"‹2›\":    return Math.PI * shape.r ** 2;   // 这里 shape 是 Circle\n    case \"‹3›\":    return shape.side ** 2;          // 这里 shape 是 Square\n    default:\n      const never_: never = shape;   // 如果漏了一种，这行编译报错\n      throw new Error(`未处理的形状: ${JSON.stringify(never_)}`);\n  }\n}","marker":"‹%n›","blanks":[{"id":"b1","answer":"kind","line":2},{"id":"b2","answer":"circle","line":3},{"id":"b3","answer":"square","line":4}],"distractors":["state","name"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch10","subject":"fullstack","title":"Vue 3 + TypeScript + Pinia：响应式原理与 ref/reactive 边界","fingerprint":"63281aebd2","scenario":{"work":{"tag":"工作现场","head":"响应式入门：Proxy 代理读取收集依赖、修改触发副作用","body":"解构 reactive 对象导致响应性丢失"},"exam":{"tag":"考场视角","head":"关于 Vue 3 响应式的依赖收集，正确的是","body":"fs-ch10 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"模板里直接调重函数 vs computed","brief":"一个组件的模板里写 `{{ heavyCalc() }}`，父组件因为别的状态频繁重渲染，这个函数就被跟着调了 500 次（每次 3ms = 1.5 秒纯浪费）。改成 computed 后，它只在自己依赖的数据变化时重算——而依赖其实很少变（5 次）。把渲染次数、依赖变化次数和计算方式拖一拖，看重算次数。","params":[{"key":"renders","label":"组件渲染次数","min":10,"max":1000,"step":10,"value":500},{"key":"depsChange","label":"依赖变化次数","min":1,"max":50,"step":1,"value":5},{"key":"useComputed","label":"计算方式","min":0,"max":1,"step":1,"value":0,"labels":["模板里直接调 heavyCalc()（每次渲染都重算）","用 computed（依赖不变不重算）"]}],"metrics":[{"key":"calcRuns","label":"重算次数","expr":"if(useComputed == 1, depsChange, renders)","unit":"次","fmt":"int"},{"key":"calcMs","label":"计算总耗时","expr":"calcRuns * 3","unit":"ms","fmt":"int"}],"checks":[{"expr":"renders >= 200","label":"至少 200 次渲染（列表频繁重渲染的真实场景）"},{"expr":"depsChange <= 10","label":"依赖很少变（只变了 5 次）"},{"expr":"calcRuns <= 20","label":"重算 ≤20 次（computed 缓存的硬判据）"},{"expr":"calcMs <= 60","label":"计算总耗时 ≤60ms"}],"insight":"响应式框架里「在模板 / 渲染函数里直接调用重计算」是典型的性能反模式：渲染是**高频且常常被迫触发**的（父组件更新、兄弟状态变化都可能让本组件重渲染），而重计算本可以**只在它真正依赖的数据变化时**跑一次。computed（Vue）/ useMemo（React）/ memoized selector（状态库）做的就是这件事：① 记录依赖 → ② 依赖不变时返回缓存值、跳过计算 → ③ 只在依赖变时重算。注意 computed 不是万能药：**依赖要选得准**，把不相关的变量塞进依赖数组会让缓存频繁失效，等于又退化成每次重算。原则是「依赖 = 函数真正读到的响应式变量」。"},{"kind":"match","pairs":[{"id":1,"left":"解构 reactive 对象导致响应性丢失","right":"需要解构并保响应性时，用 toRefs(state)（或 Pinia 的 storeToRefs(store)）把每个字段转成 ref；props 用 toRef(props, 'key')"},{"id":2,"left":"在响应式对象上整体替换却指望旧引用更新","right":"原地修改而非替换：Object.assign(state, newObj) 或 state.a = newObj.a"},{"id":3,"left":"忘记 ref 要写 .value","right":"逻辑代码里一律 count.value 读写"},{"id":4,"left":"对 Proxy 手写的玩具响应式发现 push 不触发","right":"若自研响应式，必须在 get 拦截里对数组方法包一层：调用原方法后手动派发 length 及索引"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"选择**正确**的描述。","title":"关于 Vue 3 响应式的依赖收集，正确的是","options":[{"key":"A","text":"依赖关系在组件创建时一次性固定，之后不再变化"},{"key":"B","text":"effect 运行时会把读过的字段登记到 (对象, 字段) -> effect 集合 的索引里（track），字段改写时再通知这些 effect（trigger）"},{"key":"C","text":"Vue 3 仍用 Object.defineProperty，只是做了性能优化"},{"key":"D","text":"只有模板渲染函数会被收集为依赖，watch 和 computed 不受影响"}],"correct":["B"],"explain":"Vue 3 用 Proxy + 全局 activeEffect：effect 运行时读字段触发 get 拦截执行 track，把 activeEffect 登记进 (target,key)->Set(effects) 的 WeakMap；字段改写触发 set 拦截执行 trigger 通知。依赖是随控制流动态重收集的（每次重跑先 cleanup 再收集），故 A 错。Vue 3 用 Proxy 而非 defineProperty，C 错。watch/computed 也是 effect，都会被收集，D 错。"},{"id":"q3","stem":"关于 shallowRef，正确的是","title":"shallowRef 与 ref 的差别","options":[{"key":"A","text":"shallowRef 完全不能触发，等于普通变量"},{"key":"B","text":"shallowRef 只对 .value 的整体替换做响应，内部对象的字段改动不触发"},{"key":"C","text":"shallowRef 比 ref 更深，会递归代理内部所有层级"},{"key":"D","text":"shallowRef 是 ref 的语法糖，二者运行时完全一致"}],"correct":["B"],"explain":"shallowRef 只对 .value 被整体替换（x.value = newObj）做响应，内部对象不被递归代理，所以 x.value.field = 1 不会触发更新。它是用来明确「只关心引用替换、不关心内部」的边界声明，不是语法糖也不是完全无效。需要强制派发可用 triggerRef。"},{"id":"q7","stem":"关于 Pinia 的 Setup 写法，正确的是","title":"Pinia Setup 写法的描述，正确的是","options":[{"key":"A","text":"必须在 store 里写 mutations 才能改状态"},{"key":"B","text":"store 内部直接用 ref/computed/function 定义状态、派生与行为，返回要暴露的成员即可"},{"key":"C","text":"Setup 写法无法在一个 store 里调用另一个 store"},{"key":"D","text":"Setup 写法不支持 TypeScript 类型推导"}],"correct":["B"],"explain":"Setup 写法复用 Vue 组合式 API：用 ref 定义状态、computed 定义派生、function 定义 action，return 出要暴露的成员，没有 mutation 概念（A 错）。store 间可相互 useOtherStore() 调用（C 错），且基于 TS 原生推断、类型推导很好（D 错）。"}]},{"kind":"fill","lang":"ts","file":"04-snippets.md","code":"import { defineStore } from 'pinia'\nexport const useCartStore = defineStore('cart', {\n  ‹1›: () => ({ items: [] as string[] }),\n  ‹2›: { count: (s) => s.items.length },\n  actions: { add(i: string) { this.items.push(i) } },\n})","marker":"‹%n›","blanks":[{"id":"b1","answer":"state","line":3},{"id":"b2","answer":"getters","line":4}],"distractors":["name","number"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch11","subject":"fullstack","title":"Spring Boot 3 工程骨架：分层边界、异常与校验收口","fingerprint":"d1f2036739","scenario":{"work":{"tag":"工作现场","head":"分层调用：controller -> service -> repository …","body":"在 Controller 里直接写 SQL / 调 Repository"},"exam":{"tag":"考场视角","head":"关于 Spring Boot 的分层依赖方向","body":"fs-ch11 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"事务边界放在 Controller","brief":"一个下单接口，把数据库事务开在 Controller，包住了整个 HTTP 处理流程——其中还嵌着 5 次对其它微服务的 RPC 调用（每次 100ms）。事务一直持着数据库连接和行锁，505ms 里连接池被占着，并发一高就耗尽。把事务范围、RPC 次数和耗时拖一拖，看持锁时间。","params":[{"key":"inTxnCalls","label":"事务内的远程调用数","min":0,"max":10,"step":1,"value":5},{"key":"txnScope","label":"事务范围","min":0,"max":1,"step":1,"value":0,"labels":["事务包住整个 HTTP 处理（含 RPC / IO）","事务只在 Service 内部（短事务）"]},{"key":"rpcMs","label":"单次 RPC 耗时","min":10,"max":500,"step":10,"value":100}],"metrics":[{"key":"holdingMs","label":"事务持锁时间","expr":"if(txnScope == 1, 5, inTxnCalls * rpcMs + 5)","unit":"ms","fmt":"int"},{"key":"connHeld","label":"连接被占用","expr":"holdingMs","unit":"ms","fmt":"int"}],"checks":[{"expr":"inTxnCalls >= 3","label":"业务确实跨多个服务（≥3 次远程调用）"},{"expr":"rpcMs >= 50","label":"单次 RPC 至少 50ms（网络调用真实耗时）"},{"expr":"holdingMs <= 50","label":"事务持锁 ≤50ms（短事务的硬判据）"}],"insight":"事务边界是后端最容易被放错的地方。**事务应该尽可能短、只包住真正的写操作**，决不该把 RPC / HTTP 调用 / 耗时计算裹在里面——这些都在占用数据库连接（连接池是稀缺资源）和数据库锁，并发稍高连接池就耗尽、请求开始排队。正确的分层是：Controller 负责协议转换与编排，**事务开在 Service 方法内部**，进入 Service 前先完成所有远程调用拿到数据，Service 里只做「读-算-写」的短事务。跨服务的「分布式事务」更不该用长事务硬撑，而是用 Saga / 本地消息表 / 最终一致。"},{"kind":"match","pairs":[{"id":1,"left":"在 Controller 里直接写 SQL / 调 Repository","right":"Controller 只注入 Service，由 Service 注入 Repository"},{"id":2,"left":"业务异常被当系统异常处理、堆栈返前端","right":"区分 BizException（带 code+userMessage，可安全展示）与系统异常（只返「系统繁忙」+记日志，响应体不含 e 的任何内容）"},{"id":3,"left":"把 Entity 直接当 DTO 序列化返前端","right":"定义专门的出站 VO/DTO，只含前端该看的字段，在转换层（converter/MapStruct）显式映射；用 @JsonIgnore 兜底隐藏敏感字段"},{"id":4,"left":"校验写在 service 里而非边界 DTO","right":"把格式约束放到入站 DTO 的 Jakarta 注解上（@NotNull/@Size/@Pattern），controller 用 @Validated 触发，advice 统一收集 fieldErrors 返回"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"正确的是","title":"关于 Spring Boot 的分层依赖方向","options":[{"key":"A","text":"Repository 可以依赖 Service，以便复用业务逻辑"},{"key":"B","text":"依赖方向应单向向下：Controller -> Service -> Repository，反向禁止"},{"key":"C","text":"Controller 直接调 Repository 没关系，只要能跑通"},{"key":"D","text":"Service 应当依赖 Controller，因为请求是从 Controller 进来的"}],"correct":["B"],"explain":"分层依赖必须单向向下：controller 依赖 service，service 依赖 repository，反向/跨层会破坏抽象、让事务与测试失控。A/C/D 都颠倒了方向，是典型的腐化起点。"},{"id":"q3","stem":"「用户名长度 2-10、手机号符合正则」这类格式约束，最合理的落点是","title":"Jakarta 校验应放在哪一层","options":[{"key":"A","text":"写在 Service 方法开头的一堆 if 里"},{"key":"B","text":"写在 Repository 的 SQL 里"},{"key":"C","text":"写在入站 DTO 的 Jakarta 注解上，由 Controller 的 @Validated 触发"},{"key":"D","text":"写在 Vue 前端，后端不用管"}],"correct":["C"],"explain":"格式类约束是「边界问题」，应声明式地写在入站 DTO 的注解（@NotNull/@Size/@Pattern）上，controller 用 @Validated 触发，框架在进方法体前统一校验并收集 fieldErrors。写在 service 的 if 会重复且绕过统一错误结构；只放前端则后端失去防护。"},{"id":"q7","stem":"关于二者在统一异常里的处理，正确的是","title":"业务异常 vs 系统异常的处理","options":[{"key":"A","text":"都直接把 e.getMessage() 返给前端，方便排查"},{"key":"B","text":"业务异常给业务码+友好提示（可展示），系统异常只返中性提示并记日志（藏堆栈）"},{"key":"C","text":"系统异常比业务异常严重，所以也不该记录日志"},{"key":"D","text":"二者应该合并成一个异常类，用布尔字段区分"}],"correct":["B"],"explain":"业务异常是「请求在业务上不成立」，可预期、要给用户友好提示+业务码；系统异常是故障，用户看不懂也不该看，前端只收「系统繁忙」，真实原因写服务端日志供排查。A 泄露敏感信息；C 说反了（系统异常更要记日志告警）；D 把两类语义混在一起，不利分类处理。"}]},{"kind":"fill","lang":"java","file":"02-unified-exception.md","code":"@RestControllerAdvice\npublic class GlobalExceptionHandler {\n    @ExceptionHandler(BizException.class)\n    public ResponseEntity<ApiError> handleBiz(BizException e) {\n        return ResponseEntity.status(e.‹1›())\n               .body(new ApiError(e.getCode(), e.getMessage()));\n    }\n    @ExceptionHandler(Exception.class)\n    public ResponseEntity<ApiError> handleOther(Exception e) {\n        // 系统异常：只给模糊提示，详情记日志\n        log.error(\"unexpected\", e);\n        return ResponseEntity.status(500)\n               .body(new ApiError(5000, \"系统繁忙，请稍后再试\"));\n    }\n}","marker":"‹%n›","blanks":[{"id":"b1","answer":"getHttpStatus","line":5}],"distractors":["consumer","synchronized"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch12","subject":"fullstack","title":"服务拆分与网关：拆分判断、网关职责、配置中心","fingerprint":"63ef489b2a","scenario":{"work":{"tag":"工作现场","head":"拆分触发判断：单体积分 vs 成长中的单体","body":"微服务炫技：还没到触发条件就拆"},"exam":{"tag":"考场视角","head":"关于「什么时候该拆」，正确的是","body":"fs-ch12 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"微服务跨服务调用开销","brief":"一个「下单」请求在微服务架构里要依次穿过 3 个服务（用户→库存→订单），每跳一次 RPC 都多约 2ms（1ms 网络往返 + 序列化/反序列化）。本次请求凭空多 8.4ms 延迟。单体架构里这只是一次进程内方法调用，延迟为 0。把跨服务跳数、架构和序列化体量拖一拖，看额外延迟。","params":[{"key":"svcHops","label":"本次请求跨服务跳数","min":1,"max":10,"step":1,"value":3},{"key":"arch","label":"架构","min":0,"max":1,"step":1,"value":1,"labels":["单体（进程内方法调用）","微服务（每跳一次 RPC）"]},{"key":"serializeKB","label":"每次 RPC 序列化数据","min":1,"max":64,"step":1,"value":8}],"metrics":[{"key":"perHopMs","label":"每跳额外延迟","expr":"if(arch == 0, 0, 2 + serializeKB * 0.1)","unit":"ms","fmt":"fix2"},{"key":"extraLatency","label":"本次请求额外延迟","expr":"svcHops * perHopMs","unit":"ms","fmt":"fix2"}],"checks":[{"expr":"svcHops >= 2","label":"业务确实跨多个服务"},{"expr":"extraLatency <= 5","label":"额外延迟 ≤5ms（默认微服务 8.4ms 过不了，需减少跨服务跳数 / 合并调用）"}],"insight":"「微服务」不是免费的：**每一次跨进程调用都比进程内方法调用多出网络往返 + 序列化/反序列化 + 重试/超时治理的成本**。翻过几道服务边界后，原本 1ms 的调用可能变成 5~10ms，且任何一跳抖动都会放大成端到端延迟。这章的核心不是「微服务好 / 单体好」，而是**何时拆**：当团队结构（康威定律）、独立部署粒度、技术异构需求真的出现时，付出的延迟与运维代价才值回票价；否则「为了微服务而微服务」只会在延迟和排障复杂度上双倍买单。降低开销的工程手段：合并相邻的同步 RPC、对非实时结果用异步事件、用 gRPC/protobuf 压缩序列化。"},{"kind":"match","pairs":[{"id":1,"left":"微服务炫技：还没到触发条件就拆","right":"先在单体内用包/目录边界切、强制单向依赖；等某个模块真的需要独立部署/团队时再拆"},{"id":2,"left":"按技术层拆而不是按限界上下文拆","right":"按限界上下文划边界：把「总是一起变、数据自己闭环」的一块划为一个服务，跨上下文只通过稳定接口/事件通信"},{"id":3,"left":"把业务逻辑塞进网关","right":"网关只做路由/鉴权(身份)/限流/TLS/traceId；业务决策下沉到对应服务"},{"id":4,"left":"网关限流用裸固定窗口导致临界突变","right":"改用令牌桶/漏桶，允许平滑突发又限制速率；限流只是保护闸，配合配额、风控、WAF，别把它当唯一防线"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"选择**正确**的描述。","title":"关于「什么时候该拆」，正确的是","options":[{"key":"A","text":"只要团队技术上「想用微服务」，就应该立刻从单体拆开"},{"key":"B","text":"微服务能消灭系统复杂度，是单体演进的必然终态"},{"key":"C","text":"拆分的真实触发信号多来自组织与演进层面（部署耦合、多团队、伸缩不一致），而非技术潮流"},{"key":"D","text":"按技术分层（controller/service/dao）拆分，能得到清晰的微服务边界"}],"correct":["C"],"explain":"拆分的回报来自部署耦合、团队踩脚、伸缩诉求不一致等组织/演进信号被满足；微服务把复杂度从代码内部搬到基础设施与协作上，并不消灭它。按技术层拆分只会得到「分布式单体」。所以 A、B、D 都错，C 正确。"},{"id":"q3","stem":"下列工作中，哪一项**不该**放在 API 网关？","title":"网关不应该承担的职责是","options":[{"key":"A","text":"统一校验请求身份（鉴权）并注入可信声明"},{"key":"B","text":"按路径把请求路由到对应上游服务"},{"key":"C","text":"具体的下单优惠计算与风控规则"},{"key":"D","text":"入口处统一打 traceId 与限流"}],"correct":["C"],"explain":"网关应保持「薄」，只管横切且稳定的关注点（路由、鉴权身份、限流、traceId）。优惠计算、风控是易变的领域逻辑，放网关会让它变成无人敢改的胖单点，且每次业务变更都要动入口。所以 C 是不该放的。"},{"id":"q7","stem":"选择**正确**的做法。","title":"关于密钥管理，正确的是","options":[{"key":"A","text":"为了方便，把 API Key 写在源码里并提交到 Git"},{"key":"B","text":"密钥经环境变量/密钥管理服务在运行时注入，日志中掩码，启动缺失则 fail-fast"},{"key":"C","text":"把密钥写进前端 bundle，前端直接调用第三方接口最方便"},{"key":"D","text":"密钥即使提交到 Git，事后删除提交记录即可彻底清除"}],"correct":["B"],"explain":"Git 历史不可篡改，删除提交无法清除已泄露的密钥，补救只能旋转（rotate）。前端包任何人可反编译，绝不放密钥。正确做法是运行时注入、日志掩码、缺失即 fail-fast。A、C、D 都是典型事故来源。"}]}]},
  {"chapter":"fs-ch13","subject":"fullstack","title":"前端测试与质量门禁：测试金字塔、E2E、契约测试","fingerprint":"4e46de4762","scenario":{"work":{"tag":"工作现场","head":"测试金字塔比例校验：健康 vs 倒金字塔","body":"倒金字塔：E2E 写得比单测还多"},"exam":{"tag":"考场视角","head":"测试金字塔的健康比例是","body":"fs-ch13 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"测试金字塔倒挂","brief":"一个项目写了 300 个端到端（e2e）测试、每个跑 5 秒，单元测试却只有 1000 个。一次完整回归要把浏览器拉起来跑 25 分钟，开发等得抓狂，还动不动 flaky。把 e2e 数量、单测数量以及各自的耗时拖一拖，看一次回归总时长。","params":[{"key":"e2eCount","label":"e2e 测试数","min":0,"max":500,"step":10,"value":300},{"key":"unitCount","label":"单元测试数","min":0,"max":10000,"step":100,"value":1000}],"metrics":[{"key":"e2eTotalS","label":"e2e 总耗时","expr":"e2eCount * 5","unit":"秒","fmt":"int"},{"key":"unitTotalS","label":"单测总耗时","expr":"unitCount * 10 / 1000","unit":"秒","fmt":"int"},{"key":"totalMin","label":"一次回归总时长","expr":"(e2eTotalS + unitTotalS) / 60","unit":"分钟","fmt":"fix2"},{"key":"e2eRatio","label":"e2e 占比","expr":"if(e2eCount + unitCount > 0, e2eCount * 100 / max(e2eCount + unitCount, 1), 0)","unit":"%","fmt":"int"}],"checks":[{"expr":"e2eCount >= 50","label":"确实堆了大量 e2e（这是要改的现状）"},{"expr":"e2eRatio <= 10","label":"e2e 占比 ≤10%（金字塔的硬判据）"},{"expr":"totalMin <= 15","label":"一次回归 ≤15 分钟"}],"insight":"经典的**测试金字塔**：底层大量快、稳、便宜的单元测试，中层少量集成测试，顶层极少脆弱又慢的 e2e。倒挂（e2e 一大堆、单测寥寥）会同时踩三个坑：① e2e 慢（拉浏览器/建库/走网络），回归时间随用例数线性膨胀；② e2e 易 flaky（环境/时序任一抖动就红），降低团队对测试红绿的信任；③ 失败时定位难——e2e 只告诉你「端到端挂了」，得自己往下挖。纠偏：把能落单测的逻辑（算法、校验、状态机）下沉到底层，e2e 只覆盖「关键用户旅程的冒烟」；单测用真实实现而非满屏 mock，才能既快又真。"},{"kind":"match","pairs":[{"id":1,"left":"倒金字塔：E2E 写得比单测还多","right":"把大量交互用例下沉到组件测试，逻辑下沉到单测；E2E 只覆盖几条不能挂的关键旅程，比例回到约 70/20/10"},{"id":2,"left":"用固定 sleep 等待异步","right":"改用「等待条件成立」：Playwright 的 web-first 断言自动重试，或自己写轮询 waitFor；断言针对不变量而非时刻"},{"id":3,"left":"选择器绑死 DOM 细节","right":"首选 data-testid，其次用 role/text/label 这类「用户如何感知元素」的查询；选择器绑定契约而非实现细节"},{"id":4,"left":"过度 Mock：测试绑死了实现细节","right":"用 Mock 只验证真正的协作契约（如「确实发了通知」），用 Fake/Spy 替代对内部调用细节的断言；优先测可观察行为"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"关于测试分层比例，最符合「金字塔」原则的是","title":"测试金字塔的健康比例是","options":[{"key":"A","text":"单元测试最少，E2E 最多（冰淇淋锥）"},{"key":"B","text":"单元:集成:E2E 大致 70:20:10"},{"key":"C","text":"三层各占三分之一，均匀用力"},{"key":"D","text":"只写 E2E，因为最贴近用户最可靠"}],"correct":["B"],"explain":"金字塔强调底层单测多而快、顶层 E2E 少而关键，经验比例约 70/20/10。A 是反模式（慢且 flaky），C 没有体现反馈速度差异，D 忽视单测的速度与隔离价值。"},{"id":"q3","stem":"选择**正确**的描述。","title":"关于消费者驱动契约（CDC），正确的是","options":[{"key":"A","text":"由提供者定义接口，消费者被动适应，提供者改了消费者自然跟上"},{"key":"B","text":"消费者先写「我期望提供者返回什么」生成契约，提供者在自己 CI 重放验证"},{"key":"C","text":"契约测试需要拉起所有微服务做全链路联调才能跑"},{"key":"D","text":"契约只校验状态码即可，字段细节不重要"}],"correct":["B"],"explain":"CDC 反转了传统方向：消费者声明期望并生成契约，提供者在自身 CI 重放，破坏性改动当场红，不用等联调/生产。契约测试各自独立跑、不需拉起全部依赖（C 错）；契约必须校验关键字段类型与存在性，只认状态码会漏掉字段级破坏（D 错）。"},{"id":"q7","stem":"为了降低测试对 UI 变更的敏感度，定位元素应优先使用","title":"E2E 选择器策略，最稳定的是","options":[{"key":"A","text":"深层 CSS 路径如 #app > div:nth-child(2) .btn"},{"key":"B","text":"基于视觉位置的 class 与嵌套层级"},{"key":"C","text":"专门为测试打的 data-testid 标记"},{"key":"D","text":"随文案变化的文本精确匹配"}],"correct":["C"],"explain":"data-testid 与样式、文案、DOM 层级完全解耦，UI 怎么改只要测试标记不动测试就不红，最稳。CSS 路径与层级（A、B）绑死实现细节，文案（D）易变，都不如 data-testid 稳定。"}]}]},
  {"chapter":"fs-ch14","subject":"fullstack","title":"Agent × 全栈工程接缝：流式、长任务、幂等与成本","fingerprint":"73b134ce34","scenario":{"work":{"tag":"工作现场","head":"流式透传：后端逐块产生、网关逐块转发、客户端拼接","body":"网关把流读光再返回，流式体验消失"},"exam":{"tag":"考场视角","head":"关于流式穿过网关，正确的是","body":"fs-ch14 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"流式响应逐 token 推送","brief":"一个 LLM 网关要把生成的回复流式推给客户端。如果每产出一个 token 就立即 flush 一次 HTTP chunk，1000 个 token 就是 1000 个极小的网络包（每包几字节），TCP/HTTP 头部开销被放大。改成每攒够约 8 个 token 再发一次，包数降 8 倍。把 token 数、每包 flush 间隔和是否缓冲拖一拖，看网络包数。","params":[{"key":"tokens","label":"本次响应 token 数","min":100,"max":4000,"step":100,"value":1000},{"key":"flushEvery","label":"每多少 token flush 一次","min":1,"max":64,"step":1,"value":1},{"key":"buffered","label":"缓冲策略","min":0,"max":1,"step":1,"value":0,"labels":["每生成 1 个 token 立即 flush","按 ~8 token 批量缓冲再发"]}],"metrics":[{"key":"packets","label":"网络包数","expr":"if(buffered == 1, tokens / 8, tokens / flushEvery)","unit":"个","fmt":"int"},{"key":"perPacketTokens","label":"每包 token 数","expr":"if(buffered == 1, 8, flushEvery)","unit":"个","fmt":"int"}],"checks":[{"expr":"tokens >= 500","label":"至少 500 个 token（长回复的真实体量）"},{"expr":"packets <= 200","label":"网络包 ≤200 个（批量缓冲的硬判据）"},{"expr":"perPacketTokens >= 4","label":"每包 ≥4 个 token（别发极小的包）"}],"insight":"流式（streaming）把「等全部生成完再返回」变成「边生成边推」，首字延迟（TTFT）大幅下降、体验更好；但**推送的粒度**有讲究：每产出 1 个 token 就 flush 一次，等于把 TCP 包和 HTTP chunk 头部的开销放大了几百倍，在网关 / CDN / 客户端还会触发过多的小包调度。工程上普遍做法是**攒一小批（~8 个 token，或按 ~50ms 时间窗）再 flush 一次**，既保持「打字机」体感，又把包数降一个数量级。另一个关联坑是**背压**：客户端消费慢时网关要停推，否则缓冲堆积把内存吃掉；以及 `Content-Type: text/event-stream` 下有些代理会缓冲，需要 `X-Accel-Buffering: no` 关掉。"},{"kind":"match","pairs":[{"id":1,"left":"网关把流读光再返回，流式体验消失","right":"改为字节级透传：用 for await (const chunk of response.body) 收到一块立刻 writable.write(chunk)，绝不在中间件里把流读光"},{"id":2,"left":"流式请求没有首字节超时，上游挂了前端一直转","right":"设三级超时：连接超时（快速暴露连不上）、首字节超时（快速暴露上游没产出）、整体超时（兜底）"},{"id":3,"left":"用户关页面后还在烧 token（取消没传播）","right":"用 AbortController 把取消信号从网关显式传到模型调用；任何一跳断开都触发上游停止生成"},{"id":4,"left":"长任务占着连接跑几分钟，任一超时即前功尽弃","right":"改为「创建任务返回 id → 轮询/SSE 查状态 → 取结果」三段式；状态机落库，进度写检查点"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"选择**正确**的描述。","title":"关于流式穿过网关，正确的是","options":[{"key":"A","text":"网关应在中间件里 await response.text() 把流读光再返回，这样最稳定"},{"key":"B","text":"网关应做字节级透传，收到一块立刻转发一块，避免缓冲整条响应"},{"key":"C","text":"SSE 需要像 WebSocket 一样独立握手一条全双工长连接"},{"key":"D","text":"流式请求只要设一个整体超时即可，不需要首字节超时"}],"correct":["B"],"explain":"流式网关的核心是「透传而非缓冲」：用 for await (chunk) 逐块转发，否则首字节延迟极高且内存随流增长。A 正是反面教材；SSE 复用普通 HTTP、无需独立握手（C 错）；首字节超时用于快速暴露上游无产出，不能省（D 错）。"},{"id":"q4","stem":"关于令牌桶（token bucket）与漏桶（leaky bucket），正确的是","title":"令牌桶与漏桶的区别","options":[{"key":"A","text":"两者都强制恒定输出速率，不允许任何突发"},{"key":"B","text":"令牌桶允许短时突发（桶内有存量时），漏桶强制平滑输出"},{"key":"C","text":"漏桶允许短时突发，令牌桶强制平滑"},{"key":"D","text":"两者没有区别，只是名字不同"}],"correct":["B"],"explain":"令牌桶以固定速率加令牌，请求取令牌，桶里有存量时允许短时突发；漏桶以固定速率漏出，强制输出平滑、不允许突发。API 限流通常选令牌桶（容忍突发），保护下游数据库时才用漏桶（强制平滑）。"}]},{"kind":"fill","lang":"js","file":"01-streaming-through-gateway.md","code":"async function* backend() {\n  for (const t of [\"思考中…\", \"检索知识库\", \"生成：你好\", \"，我是助手\"]) {\n    await new Promise(r => ‹1›(r, 5));\n    yield `data: ${t}\\n\\n`;\n  }\n}\nasync function gateway(src, sink) {\n  for await (const chunk of src) sink.‹2›(chunk); // 收到一块立刻转发一块\n}","marker":"‹%n›","blanks":[{"id":"b1","answer":"setTimeout","line":3},{"id":"b2","answer":"push","line":8}],"distractors":["json","body"],"tip":"把缺失的标识符拖回代码里的空位 —— 位置对、词对才算补回来。"}]},
  {"chapter":"fs-ch15","subject":"fullstack","title":"Go + Gin 后端：并发模型、接口契约与 Java 路线对照","fingerprint":"00fee729a1","scenario":{"work":{"tag":"工作现场","head":"Goroutine 并发：N 个 goroutine 经 channel 汇总（无…","body":"goroutine 泄漏：开了没退出条件"},"exam":{"tag":"考场视角","head":"关于 Goroutine 与 Channel，正确的是","body":"fs-ch15 · 本章真题口径"}},"modules":[{"kind":"sandbox","title":"无锁并发计数丢更新","brief":"用 Go 起 100 个 goroutine，每个对同一个共享计数器自增 1000 次。如果直接 `counter++`（没有锁、没有 atomic），自增在 CPU 上是「读-改-写」三步，多个 goroutine 会读到同一个旧值一起写回，互相覆盖——最终计数远小于 100×1000。把协程数、每协程次数和保护方式拖一拖，看最终值是否精确。","params":[{"key":"goroutines","label":"并发 goroutine 数","min":10,"max":1000,"step":10,"value":100},{"key":"perG","label":"每协程自增次数","min":100,"max":10000,"step":100,"value":1000},{"key":"useMutex","label":"保护方式","min":0,"max":1,"step":1,"value":0,"labels":["共享变量直接 counter++（无锁）","用 atomic / mutex 保护"]}],"metrics":[{"key":"expected","label":"期望最终值","expr":"goroutines * perG","unit":"次","fmt":"int"},{"key":"lost","label":"丢失的更新","expr":"if(useMutex == 1, 0, round(expected * 0.4))","unit":"次","fmt":"int"},{"key":"final","label":"实际最终值","expr":"expected - lost","unit":"次","fmt":"int"}],"checks":[{"expr":"goroutines >= 50","label":"至少 50 个并发协程（真实并发场景）"},{"expr":"perG >= 500","label":"每协程至少自增 500 次"},{"expr":"final == expected","label":"最终值 == 期望值（加锁的硬判据）"}],"insight":"`counter++` 看起来是一行，在机器码里是「从内存读 → 寄存器 +1 → 写回内存」三步，**根本不是原子的**。两个 goroutine 同时读到 42、都算成 43、都写回 43——一次自增就这么丢了。高并发下丢失比例可观（上面默认丢 40%）。四种修法按场景选：① **sync/atomic**（整数/指针计数器最轻量，无锁但用 CPU 原子指令）；② **mutex**（保护任意临界区，代价是串行化）；③ **channel** 把计数收拢到一个 owner goroutine（「不要通过共享内存来通信」的 Go 哲学）；④ 如果每个协程只管自己的局部计数，最后再汇总（避免共享），最优雅。写完记得 `go run -race` 跑一遍，race detector 能直接揪出这类数据竞争。"},{"kind":"match","pairs":[{"id":1,"left":"goroutine 泄漏：开了没退出条件","right":"给 goroutine 配退出信号：用 context.Context 的 Done() 或关闭的 channel 来通知退出；长驻 goroutine 必须有「何时结束」的明确路径"},{"id":2,"left":"多个 goroutine 共享变量却不上锁","right":"把「+1」作为事件发到 channel，由一个汇总 goroutine 收；或者确需共享时用 sync.Mutex/atomic，但优先用 channel"},{"id":3,"left":"无缓冲 channel 没人接收导致永久阻塞","right":"明确收发双方的生命周期；用 select + default 或带超时的 time.After 避免永久阻塞；发送前确认接收方已就绪或会用 close 收尾"},{"id":4,"left":"A Tour of Go 式误用：向已关闭的 channel 发送","right":"关闭 channel 的责任要唯一：只让「唯一的发送方」或「协调者」关闭；多生产者场景用 sync.WaitGroup 等全部发完再由唯一方关闭"}],"tip":"左边是线上真出事的写法，右边是正确做法。一对一连上才算过。"},{"kind":"boss","questions":[{"id":"q0","stem":"选择**正确**的描述。","title":"关于 Goroutine 与 Channel，正确的是","options":[{"key":"A","text":"goroutine 初始栈约 1MB，和 Java 线程一样重"},{"key":"B","text":"无缓冲 channel 的 send 会一直阻塞，直到有 receive 接住（会合语义）"},{"key":"C","text":"多个 goroutine 直接共享变量 count++ 是安全的，不需要任何同步"},{"key":"D","text":"channel 只能传数据，不能用作同步原语"}],"correct":["B"],"explain":"goroutine 初始栈仅约 2KB（A 错）；无缓冲 channel 的 send 必须等 receive 接住才返回，这是会合语义（B 对）。共享变量 count++ 在 Go 里仍是数据竞争（C 错）；channel 本身就是语言内建的同步原语（D 错）。"},{"id":"q4","stem":"关于 Go 的错误处理，正确的是","title":"Go 的 error 与 Java 异常对照，正确的是","options":[{"key":"A","text":"Go 用异常机制捕获错误，和 Java try/catch 一样"},{"key":"B","text":"Go 把错误作为普通返回值，调用方需显式 if err != nil 检查"},{"key":"C","text":"可预期的失败（网络超时）应该用 panic 抛出让 recover 兜住"},{"key":"D","text":"Go 接口必须由实现方声明 implements 才算实现"}],"correct":["B"],"explain":"Go 没有异常（panic 只给不可恢复状态），错误是普通返回值，调用点必须显式检查（B 对）。可预期失败要用 error 返回而非 panic（C 错）；Go 接口是结构化的、由消费者定义、满足方法集即实现，无需 implements（D 错）。"}]}]},
];

export default LABS;
